// Tauri 构建脚本；同时负责视频导出渲染器的最终链接参数。

fn main() {
    // vulkan-1.dll 延迟加载: 没有 Vulkan 运行库的机器也要能启动编辑器。
    // 渲染器静态库经 webgal-video-render-sys 链进来, 而 `/DELAYLOAD` 只在最终
    // 链接生效 (依赖 crate 的 rustc-link-arg 不会传到这里)。启用 `video-export`
    // 特性才导入 vulkan-1.dll, 否则链接器会报 LNK4199。
    let windows = std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows");
    let msvc = std::env::var("CARGO_CFG_TARGET_ENV").as_deref() == Ok("msvc");
    let video_export = std::env::var_os("CARGO_FEATURE_VIDEO_EXPORT").is_some();
    if windows && msvc && video_export {
        println!("cargo:rustc-link-arg=/DELAYLOAD:vulkan-1.dll");
        println!("cargo:rustc-link-lib=delayimp");
    }
    tauri_build::build()
}
